package com.fakelegacy.order.pricing;

import java.math.BigDecimal;

public class LineDraft {

    private final String sku;
    private final String category;
    private final int quantity;
    private final BigDecimal unitBase;
    private final BigDecimal unitSale;

    private BigDecimal discountTier = BigDecimal.ZERO.setScale(2);
    private BigDecimal discountVolume = BigDecimal.ZERO.setScale(2);
    private BigDecimal discountPromo = BigDecimal.ZERO.setScale(2);
    private BigDecimal lineHt;
    private BigDecimal vatRate;
    private BigDecimal lineTtc;

    public LineDraft(String sku, String category, int quantity, BigDecimal unitBase, BigDecimal unitSale) {
        this.sku = sku;
        this.category = category;
        this.quantity = quantity;
        this.unitBase = unitBase;
        this.unitSale = unitSale;
    }

    public boolean isOnSale() {
        return unitSale != null;
    }

    /** Amount before any discount: sale price for sale items, base price otherwise. */
    public BigDecimal gross() {
        BigDecimal unit = isOnSale() ? unitSale : unitBase;
        return TaxUtils.round2(unit.multiply(BigDecimal.valueOf(quantity)));
    }

    /** Amount the promo code works on: gross minus tier and volume discounts. */
    public BigDecimal afterVolume() {
        return gross().subtract(discountTier).subtract(discountVolume);
    }

    public BigDecimal totalDiscount() {
        return discountTier.add(discountVolume).add(discountPromo);
    }

    public void recompute() {
        lineHt = gross().subtract(discountTier).subtract(discountVolume).subtract(discountPromo);
        vatRate = TaxUtils.vatRateFor(category);
        lineTtc = TaxUtils.withVat(lineHt, vatRate);
    }

    public String getSku() { return sku; }
    public String getCategory() { return category; }
    public int getQuantity() { return quantity; }
    public BigDecimal getUnitBase() { return unitBase; }
    public BigDecimal getUnitSale() { return unitSale; }

    public BigDecimal getDiscountTier() { return discountTier; }
    public void setDiscountTier(BigDecimal discountTier) { this.discountTier = discountTier; }

    public BigDecimal getDiscountVolume() { return discountVolume; }
    public void setDiscountVolume(BigDecimal discountVolume) { this.discountVolume = discountVolume; }

    public BigDecimal getDiscountPromo() { return discountPromo; }
    public void setDiscountPromo(BigDecimal discountPromo) { this.discountPromo = discountPromo; }

    public BigDecimal getLineHt() { return lineHt; }
    public BigDecimal getVatRate() { return vatRate; }
    public BigDecimal getLineTtc() { return lineTtc; }
}
